package com.bank.lag.model;

public class PartitionLag {
    private final int partition;
    private final long logEndOffset;   // latest produced offset
    private final long committedOffset; // consumer position

    public PartitionLag(int partition, long logEndOffset, long committedOffset) {
        this.partition = partition;
        this.logEndOffset = logEndOffset;
        this.committedOffset = committedOffset;
    }
    public int getPartition() { return partition; }
    public long lag() { return logEndOffset - committedOffset; }

    @Override public String toString() {
        return "P" + partition + "(end=" + logEndOffset + ",committed="
             + committedOffset + ",lag=" + lag() + ")";
    }
}
