package com.bank.lag.monitor;

import com.bank.lag.model.PartitionLag;
import java.util.*;
import java.util.logging.*;

public class LagMonitor {
    private static final Logger log = Logger.getLogger(LagMonitor.class.getName());

    private final long perPartitionThreshold;

    public LagMonitor(long perPartitionThreshold) {
        this.perPartitionThreshold = perPartitionThreshold;
    }

    public long aggregate(List<PartitionLag> lags) {
        return lags.stream().mapToLong(PartitionLag::lag).sum();
    }

    public PartitionLag maxPartition(List<PartitionLag> lags) {
        return lags.stream().max(Comparator.comparingLong(PartitionLag::lag)).orElseThrow();
    }

    // Shows why aggregate alone is misleading.
    public void evaluate(String label, List<PartitionLag> lags) {
        long agg = aggregate(lags);
        PartitionLag worst = maxPartition(lags);
        log.info(label + " aggregate lag = " + agg + " (looks the same either way)");
        if (worst.lag() >= perPartitionThreshold) {
            log.severe("  PER-PARTITION ALERT: " + worst + " exceeds threshold "
                + perPartitionThreshold + " — one partition is stuck/hot!");
        } else {
            log.info("  All partitions healthy; worst is " + worst);
        }
    }
}
