package com.bank.lag;

import com.bank.lag.model.PartitionLag;
import com.bank.lag.monitor.LagMonitor;
import java.util.*;
import java.util.logging.*;

public class LagDemo {
    private static final Logger log = Logger.getLogger(LagDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LagMonitor monitor = new LagMonitor(500);

        // Case A: healthy spread — 50 lag on each of 12 partitions, aggregate 600.
        List<PartitionLag> healthy = new ArrayList<>();
        for (int p = 0; p < 12; p++) healthy.add(new PartitionLag(p, 1000 + 50, 1000));
        monitor.evaluate("HEALTHY ", healthy);

        // Case B: SAME aggregate 600, but all of it on ONE stuck partition.
        List<PartitionLag> stuck = new ArrayList<>();
        stuck.add(new PartitionLag(3, 1600, 1000)); // lag 600 — stuck on poison pill
        for (int p = 0; p < 12; p++) if (p != 3) stuck.add(new PartitionLag(p, 1000, 1000)); // lag 0
        monitor.evaluate("STUCK   ", stuck);

        log.warning("Same aggregate (600) — only per-partition view reveals the stuck partition.");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
